	"dash.readinessFromLoadOnly": "Calculada apenas a partir da sua carga de treino. O sono e a frequência cardíaca em repouso ainda não são considerados.",
	"dash.vo2maxTooltip": "VO₂ máx — o seu motor aeróbico: quanto oxigénio o seu corpo consegue utilizar por minuto. Quanto maior, mais em forma.",
	"metric.vo2max.label": "VO₂ máx",
	"metric.ageGrade.label": "Grau por idade",
	"metric.ageGrade.definition": "Grau por idade — o seu tempo comparado com o melhor registo para a sua idade e sexo. Cerca de 60% é um bom corredor amador; 80% é nível nacional.",
	"metric.vert.label": "Ganho",
	"metric.vert.definition": "Ganho — a altura total que subiu, somando todas as subidas.",
	"metric.trimp.label": "TRIMP",
	"metric.trimp.definition": "TRIMP (impulso de treino) — uma pontuação de quão exigente foi uma corrida, a partir da duração e de quanto a sua frequência cardíaca subiu.",
	"metric.riegel.label": "fórmula de Riegel",
	"metric.riegel.definition": "Fórmula de Riegel — uma forma consagrada de prever o seu tempo numa distância a partir do tempo que fez noutra.",
	"metric.vdot.label": "VDOT",
	"metric.vdot.definition": "VDOT — uma pontuação de forma física para corredores, pela fórmula do treinador Jack Daniels, calculada a partir de um tempo de prova recente. Quanto maior, mais em forma, e os seus ritmos de treino saem dela.",
	"metric.distanceBanked.definition": "Distância acumulada — quanto da distância total deste plano já correu.",
	"metric.planPhases.label": "Fases de treino",
	"metric.planPhases.definition": "Fases de treino — Base constrói o hábito de correr leve, Construção acrescenta treinos mais duros, Pico é o bloco mais exigente, Polimento alivia a carga para chegar descansado e Semana de prova são os últimos dias leves antes da prova.",
	"metric.e1rm.definition": "1RM (uma repetição máxima) — o peso mais alto que conseguiria levantar numa única repetição. O 1RM estimado é calculado a partir do peso e das repetições de uma série que fez, por isso nunca precisa de o testar.",
	"metric.e1rm.inline": "repetição máxima estimada (1RM)",
	"metric.rpe.definition": "RPE (perceção de esforço) — o quão exigente foi uma série, de 1 a 10. Um 10 significa que não conseguiria fazer nem mais uma repetição.",
	"metric.kom.label": "KOM/QOM",
	"metric.kom.definition": "KOM/QOM (Rei / Rainha da Montanha) — a coroa pelo tempo mais rápido num segmento, uma para homens e outra para mulheres.",
	"dash.ctlTooltip": "Condicionamento (CTL) — a sua carga de treino móvel de 42 dias. Cresce devagar; é a sua base de resistência.",
