	"settingsIntegrations.title": "Integrações",
	"settingsIntegrations.tagline": "Traga as suas corridas das aplicações e relógios que já usa — ou largue um ficheiro de exportação em lote se preferir não ligar uma conta.",
	"settingsIntegrations.loading": "A carregar integrações…",
	"settingsIntegrations.emptyTitle": "Nenhuma integração ligada",
	"settingsIntegrations.emptyText": "Ligue uma conta abaixo para que as suas corridas cheguem automaticamente. Ou utilize os cartões de importação em lote se preferir largar uma exportação avulsa.",
	"settingsIntegrations.availableHeading": "Integrações disponíveis",
	"settingsIntegrations.infoAbout": "Sobre o {name}",
	"settingsIntegrations.strandedNote": "Esta ligação continua associada à sua conta, mas não consegue sincronizar aqui. Desligue-a se já não precisar dela.",
	"settingsIntegrations.stravaInfo": "O Strava é uma aplicação popular para registar e partilhar corridas. Ao ligá-lo, as suas atividades do Strava são copiadas: primeiro os últimos 90 dias e depois cada nova atividade à medida que aparece. Inicia sessão no Strava e autoriza o acesso, e pode desligar quando quiser.",
	"settingsIntegrations.parkrunInfo": "O parkrun é uma corrida de 5 km gratuita e cronometrada, realizada todas as semanas em parques por todo o mundo. Ligar regista que participa; para trazer os seus resultados, introduza o número de atleta do seu código de barras do parkrun (o que começa por A) em Definições, Conta, e escolha «Trazer resultados do parkrun».",
	"settingsIntegrations.garminInfo": "O Garmin Connect é onde um relógio Garmin guarda as suas atividades. A ligação automática de conta ainda não está disponível — a Garmin tem de a aprovar. Até lá, «Importação em lote de uma exportação Garmin», mais abaixo nesta página, traz as mesmas corridas a partir de um ficheiro, sem ligar conta nenhuma.",
	"settingsIntegrations.healthkitInfo": "O Apple HealthKit é o repositório de saúde do iPhone, onde vão parar os treinos de todas as aplicações. Só funciona no próprio dispositivo, por isso um navegador não tem a que se ligar — a sincronização acontece dentro da aplicação de iPhone.",
	"settingsIntegrations.stravaBulkInfo": "Ligar o Strava traz apenas a atividade recente. Se usa o Strava há anos, uma exportação em lote traz tudo. Peça ao Strava uma cópia dos seus dados em Definições, A minha conta, Transferir ou eliminar a sua conta; aguarde o e-mail, que pode demorar algumas horas; e largue aqui o ficheiro zip. As corridas que já tem são ignoradas.",
	"settingsIntegrations.garminBulkInfo": "Isto traz o seu histórico da Garmin a partir de um ficheiro, em vez de uma ligação de conta. Exporte uma atividade no Garmin Connect com «Exportar original», ou peça os seus dados completos na gestão de conta da Garmin e largue o zip aqui quando o e-mail chegar. As corridas que já tem são ignoradas.",
	"settingsIntegrations.stravaDescription": "Sincronize atividades automaticamente da sua conta do Strava",
	"settingsIntegrations.parkrunDescription": "Importe todo o seu histórico do parkrun",
	"settingsIntegrations.parkrunRegionNote": "O parkrun está presente apenas em alguns países e pode não haver eventos perto de si — ainda assim, pode ligá-lo se tiver um ID de atleta do parkrun.",
	"settingsIntegrations.garminDescription": "Importação em lote de ficheiros .fit (uma única atividade ou exportação completa dos dados da conta). O OAuth em direto requer aprovação do programa de desenvolvedores da Garmin.",
