	"prefs.tagline": "As suas preferências estão agrupadas pelo que alteram. Escolha um grupo para ver e editar as definições. As alterações são guardadas automaticamente e acompanham-no em todos os dispositivos em que iniciar sessão.",
	"prefs.displayTagline": "Como os números, os mapas e a própria app lhe aparecem. O idioma e o tema aplicam-se a este navegador; o resto acompanha-o em todos os dispositivos em que iniciar sessão.",
