	"prefs.privacyZonesDesc": "Oculte um raio ao redor de casa, do trabalho ou de qualquer outro lugar nas partilhas públicas de corridas e rotas. O início e o fim de qualquer trajeto que caia dentro de uma zona são recortados antes de o público ver. As visualizações do proprietário sempre mostram o trajeto completo.",
