	"deleteAccount.documentTitle": "Eliminar a sua conta — Threkir",
	"deleteAccount.metaDescription": "Como eliminar a sua conta Threkir e todos os dados associados, com ou sem a app instalada.",
	"deleteAccount.h1": "Eliminar a sua conta",
	"deleteAccount.lead": "Esta página explica como eliminar definitivamente a sua conta Threkir e os dados a ela associados. Não precisa de ter a app instalada para pedir a eliminação.",
	"deleteAccount.lastUpdated": "Última atualização: {date}",
	"deleteAccount.s1Heading": "1. Eliminar a conta por si próprio",
	"deleteAccount.s1Intro": "A eliminação é feita por si e produz efeito de imediato:",
	"deleteAccount.s1WebLabel": "Na web",
	"deleteAccount.s1WebPrefix": ": inicie sessão, abra ",
	"deleteAccount.s1WebLink": "Definições → Conta",
	"deleteAccount.s1WebMiddle": " e escolha ",
	"deleteAccount.s1WebAction": "Eliminar conta",
	"deleteAccount.s1WebSuffix": ". Para confirmar, ser-lhe-á pedido que escreva o e-mail da sua conta. (Se abrir a ligação sem sessão iniciada, passa pelo início de sessão e regressa aqui.)",
	"deleteAccount.s1MobileLabel": "Na app do telemóvel",
	"deleteAccount.s1MobileBody": ": Definições → Conta → Eliminar conta, com a mesma confirmação escrita.",
	"deleteAccount.s1PermanentPrefix": "A eliminação é ",
	"deleteAccount.s1PermanentEmphasis": "definitiva e não pode ser anulada",
	"deleteAccount.s1PermanentSuffix": ". Quando termina, enviamos um único e-mail de confirmação para o endereço da conta, como comprovativo.",
	"deleteAccount.s2Heading": "2. Se não conseguir iniciar sessão",
	"deleteAccount.s2Prefix": "Envie um e-mail para ",
	"deleteAccount.s2Suffix": " a partir do endereço de e-mail da conta e peça-nos que a eliminemos. Verificamos o pedido confirmando esse endereço (ou pedindo-lhe que confirme uma ligação enviada para ele), fazemos a mesma eliminação descrita abaixo e confirmamos quando estiver concluída — no máximo dentro de um mês, normalmente muito antes.",
	"deleteAccount.s3Heading": "3. O que é eliminado",
	"deleteAccount.s3Intro": "Eliminar a conta apaga os seus dados da nossa base de dados e do armazenamento de ficheiros, incluindo:",
	"deleteAccount.s3Profile": "o seu perfil (nome, avatar, definições, relações de seguidores);",
	"deleteAccount.s3Runs": "corridas e os respetivos trajetos GPS, rotas, resultados de provas e recordes pessoais;",
	"deleteAccount.s3Files": "fotografias e todos os outros ficheiros que carregou, incluindo exportações de dados geradas;",
	"deleteAccount.s3Gym": "treinos de ginásio, rotinas, planos de sessão, registos de alimentação e medidas corporais;",
	"deleteAccount.s3Training": "planos de treino, histórico de conversas com o Coach e registos de consentimento do Coach de IA;",
	"deleteAccount.s3Social": "publicações, comentários, kudos, mensagens diretas e participação em clubes;",
	"deleteAccount.s3Notifications": "notificações e tokens de notificações push;",
	"deleteAccount.s3ThirdParty": "recursos de terceiros associados: uma autorização do Strava ligada é revogada, um registo de subscritor do RevenueCat é eliminado e uma conta de pagamentos do Stripe ligada é desassociada e encerrada (o Stripe conserva os registos de transações ao abrigo das suas próprias obrigações legais).",
	"deleteAccount.s4Heading": "4. O que é conservado, e durante quanto tempo",
	"deleteAccount.s4BackupsLabel": "Cópias de segurança encriptadas",
	"deleteAccount.s4BackupsPrefix": ": uma conta eliminada pode permanecer nas cópias de recuperação para um momento específico durante até ",
	"deleteAccount.s4BackupsWindow": "28 dias",
	"deleteAccount.s4BackupsSuffix": ", até estas expirarem. As cópias de segurança nunca são usadas para restaurar uma conta eliminada.",
	"deleteAccount.s4AuditLabel": "Um registo mínimo da eliminação",
	"deleteAccount.s4AuditBody": ": um identificador com hash irreversível e a contagem do que foi eliminado, guardados para podermos provar que a eliminação aconteceu. Não pode ser usado para o identificar nem para recuperar quaisquer dados.",
	"deleteAccount.s4PaymentsLabel": "Registos de transações de pagamento",
	"deleteAccount.s4PaymentsBody": ": conservados pelos processadores de pagamento (Stripe, as lojas de apps) ao abrigo das suas próprias obrigações legais; nós não guardamos dados de cartões.",
	"deleteAccount.s4PolicyPrefix": "O calendário completo de conservação de cada categoria de dados está na ",
	"deleteAccount.s4PolicySuffix": ".",
	"deleteAccount.s5Heading": "5. Eliminar alguns dados sem encerrar a conta",
	"deleteAccount.s5Intro": "Para eliminar dados específicos sem eliminar a conta:",
	"deleteAccount.s5ItemsLabel": "Corridas, rotas, fotografias, treinos de ginásio, registos de alimentação, publicações, comentários",
	"deleteAccount.s5ItemsBody": ": abra o item e use a respetiva opção Eliminar. As corridas também podem ser eliminadas em lote na lista de corridas, com a seleção múltipla.",
	"deleteAccount.s5ServicesLabel": "Serviços ligados",
	"deleteAccount.s5ServicesBody": " (Strava, parkrun e semelhantes): desligue-os em Definições → Integrações; ao desligar, o nosso acesso é revogado.",
	"deleteAccount.s5OtherLabel": "Qualquer outra coisa, ou se preferir não o fazer na app",
	"deleteAccount.s5OtherPrefix": ": envie um e-mail para ",
	"deleteAccount.s5OtherSuffix": " a descrever os dados a eliminar, e trataremos disso com a mesma verificação e o mesmo prazo da secção 2.",
	"deleteAccount.s5BackupsPrefix": "Os itens eliminados saem das cópias de segurança encriptadas dentro do mesmo prazo de 28 dias descrito acima. Também pode ",
	"deleteAccount.s5ExportLink": "exportar os seus dados",
	"deleteAccount.s5BackupsSuffix": " antes de eliminar o que quer que seja.",
	"deleteAccount.s6Heading": "6. Documentos relacionados",
